package com.vahotel.service;
import com.vahotel.model.*;import com.vahotel.repo.*;import java.math.BigDecimal;import java.time.LocalDate;import java.time.temporal.ChronoUnit;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ReservationService {private final ReservationRepository reservations;public ReservationService(ReservationRepository r){reservations=r;}
 @Transactional public Reservation create(Account customer,Room room,LocalDate in,LocalDate out){return create(customer,room,in,out,"REGULAR",false);}
 @Transactional public Reservation create(Account customer,Room room,LocalDate in,LocalDate out,String bookingType){return create(customer,room,in,out,bookingType,false);}
 @Transactional public Reservation createWalkIn(Account customer,Room room,LocalDate in,LocalDate out){return create(customer,room,in,out,"WALK_IN",true);}
 private Reservation create(Account customer,Room room,LocalDate in,LocalDate out,String bookingType,boolean allowToday){LocalDate today=LocalDate.now(java.time.ZoneId.of("Asia/Manila"));boolean invalidCheckIn=in==null||(allowToday?in.isBefore(today):!in.isAfter(today));if(invalidCheckIn||out==null||!out.isAfter(in))throw new IllegalArgumentException(allowToday?"Choose today or a future check-in date and a later check-out date.":"Select a future check-in and later check-out date.");if(!room.isActive())throw new IllegalArgumentException("Room is inactive.");if(reservations.countOverlaps(room,in,out)>0)throw new IllegalStateException("Room has an overlapping reservation.");long nights=ChronoUnit.DAYS.between(in,out);BigDecimal total=room.getNightlyPrice().multiply(BigDecimal.valueOf(nights));return reservations.save(new Reservation(customer,room,in,out,bookingType,total));}}
